  });
  const modelNodes = p.models.map((m, mi) => {
    const nodeX = 60 + ((mi + 1) / (p.models.length + 1)) * (gridW - 120);
    return e('div', {key:'m'+mi, style:{position:'absolute', left: nodeX - 30, top: gridH * 0.35, width:60, height:30, borderRadius:6, background: p.colors[mi], display:'flex', alignItems:'center', justifyContent:'center', fontSize:9, fontFamily:D.font_mono, color:D.bg, fontWeight:'bold'}}, m.split(' ').pop());
  });
