  const outputNode = e('div', {key:'out', style:{position:'absolute', right:10, top: gridH*0.42, width:44, height:22, borderRadius:4, background:D.surface, border:'1px solid '+D.green, display:'flex', alignItems:'center', justifyContent:'center', fontSize:8, fontFamily:D.font_mono, color:D.green}}, 'output');
  const line = e('div', {key:'line', style:{position:'absolute', left:54, top: gridH*0.5, width: gridW - 108, height:2, background: D.text_dim, opacity:0.4}});
  return e('div', {key:'pipe'+i, style:{position:'absolute', left:bx, top:by, width:gridW, height:gridH, background:D.surface, borderRadius:12, border:'1px solid '+D.text_dim, opacity:appear, transform:'scale('+appear+')'}},
    e('div', {style:{position:'absolute', top:8, left:0, right:0, textAlign:'center', fontSize:13, fontFamily:D.font_display, color:D.text, fontWeight:'bold'}}, p.label),
    line, inputNode, outputNode, ...modelNodes, ...dots
  );
});
const centerDelay = pipelines.length * cloneDelay + 20;
